=head2 Google::Cloud::Visionai::V1::Platform::AutoscalingMetricSpec

The metric specification that defines the target resource utilization
(CPU utilization, accelerator's duty cycle, and so on) for calculating the
desired replica count.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->metric_name() >> / C<< $msg->metric_name($value) >>

Type: C<String>

Required. The resource metric name.
Supported metrics:

* For Online Prediction:
* `aiplatform.googleapis.com/prediction/online/accelerator/duty_cycle`
* `aiplatform.googleapis.com/prediction/online/cpu/utilization`

=item * C<< $msg->target() >> / C<< $msg->target($value) >>

Type: C<Int32>

The target resource utilization in percentage (1% - 100%) for the given
metric; once the real usage deviates from the target by a certain
percentage, the machine replicas change. The default value is 60
(representing 60%) if not provided.

=back

=head2 Google::Cloud::Visionai::V1::Platform::DedicatedResources

A description of resources that are dedicated to a DeployedModel, and
that need a higher degree of manual configuration.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->machine_spec() >> / C<< $msg->machine_spec($value) >>

Type: C<Message> (L<Google::Cloud::Visionai::V1::Platform::MachineSpec>)

Required. Immutable. The specification of a single machine used by the
prediction.

=item * C<< $msg->min_replica_count() >> / C<< $msg->min_replica_count($value) >>

Type: C<Int32>

Required. Immutable. The minimum number of machine replicas this
DeployedModel will be always deployed on. This value must be greater than
or equal to 1.

If traffic against the DeployedModel increases, it may dynamically be
deployed onto more replicas, and as traffic decreases, some of these extra
replicas may be freed.

=item * C<< $msg->max_replica_count() >> / C<< $msg->max_replica_count($value) >>

Type: C<Int32>

Immutable. The maximum number of replicas this DeployedModel may be
deployed on when the traffic against it increases. If the requested value
is too large, the deployment will error, but if deployment succeeds then
the ability to scale the model to that many replicas is guaranteed (barring
service outages). If traffic against the DeployedModel increases beyond
what its replicas at maximum may handle, a portion of the traffic will be
dropped. If this value is not provided, will use
[min_replica_count][google.cloud.visionai.v1.DedicatedResources.min_replica_count]
as the default value.

The value of this field impacts the charge against Vertex CPU and GPU
quotas. Specifically, you will be charged for max_replica_count *
number of cores in the selected machine type) and (max_replica_count *
number of GPUs per replica in the selected machine type).

=item * C<< $msg->autoscaling_metric_specs() >> / C<< $msg->autoscaling_metric_specs($value) >>

Type: C<Message> (L<Google::Cloud::Visionai::V1::Platform::AutoscalingMetricSpec>)

Immutable. The metric specifications that overrides a resource
utilization metric (CPU utilization, accelerator's duty cycle, and so on)
target value (default to 60 if not set). At most one entry is allowed per
metric.

If
[machine_spec.accelerator_count][google.cloud.visionai.v1.MachineSpec.accelerator_count]
is above 0, the autoscaling will be based on both CPU utilization and
accelerator's duty cycle metrics and scale up when either metrics exceeds
its target value while scale down if both metrics are under their target
value. The default target value is 60 for both metrics.

If
[machine_spec.accelerator_count][google.cloud.visionai.v1.MachineSpec.accelerator_count]
is 0, the autoscaling will be based on CPU utilization metric only with
default target value 60 if not explicitly set.

For example, in the case of Online Prediction, if you want to override
target CPU utilization to 80, you should set
[autoscaling_metric_specs.metric_name][google.cloud.visionai.v1.AutoscalingMetricSpec.metric_name]
to `aiplatform.googleapis.com/prediction/online/cpu/utilization` and
[autoscaling_metric_specs.target][google.cloud.visionai.v1.AutoscalingMetricSpec.target]
to `80`.

=back

